func setupCheckoutSyncRepo(t *testing.T) string {
	t.Helper()
	dir := t.TempDir()
	gitRunCS(t, dir, "init", "--initial-branch=main")
	gitRunCS(t, dir, "config", "user.email", "test@test.com")
	gitRunCS(t, dir, "config", "user.name", "Test")
	writeFileCS(t, dir, ".gitignore", ".tws/\n")
